We are given an array consisting of n integers and an integer k. We need to find the smallest subarray [l, r] (both l and r are inclusive) such that there are exactly k different numbers. If no such subarray exists, print -1 and If multiple subarrays meet the criteria, return the one with the smallest starting index.Examples:Input: arr[] = { 1, 1, 2, 2, 3, 3, 4, 5}             k = 3Output: 5 7Explanation: K Different numbers are present in range of [5,7]  with the minimum range.Input: arr[] = { 1, 2, 2, 3}             k = 2Output: 0 1Explanation: K Different numbers are present in range of [0,2] , with the minimum length and index.Input: arr[] = {1, 1, 2, 1, 2}            k = 3Output: Invalid kExplanation: K Different Number is not present the array.Table of Content[Naive Approach] Generate all the Subarrays - O(n^2) Time and O(n) Space[Expected Approach] Sliding Window Approach - O(n) Time and O(k) Space[Naive Approach] Generate all the Subarrays - O(n^2) Time and O(n) SpaceWe use nested for loops to generate all possible subarrays. For each subarray, we check if it contains exactly k distinct numbers. If it does, we compare its length with the current minimum and update l and r accordingly. If not find any subarray that contain k distinct numbers return -1.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Prints the minimum range that contains exactly
// k distinct numbers.
void minRange(vector<int> &arr, int n, int k)
{
    // Starting and ending  index of resultant subarray
    int start = 0, end = n;

    // Selecting each element as the start index for
    // subarray
    for (int i = 0; i < n; i++) {
        // Initialize a set to store all distinct elements
        unordered_set<int> set;

        // Selecting the end index for subarray
        int j;
        for (j = i; j < n; j++) {
            set.insert(arr[j]);

            /*
            If set contains exactly k elements,
            then check subarray[i, j] is smaller in size
            than the current resultant subarray
            */
            if (set.size() == k) {
                if (j - i < end - start) {
                    start = i;
                    end = j;
                }

                // There are already k distinct elements
                // now, no need to consider further elements
                break;
            }
        }

        // If there are no k distinct elements
        // left in the array starting from index i we will
        // break
        if (j == n) {
            break;
        }
    }

    // If no window found then print -1
    if (start == 0 && end == n)
        cout << -1;

    else
        cout << start << " " << end;
}

// Driver code for above function.
int main()
{
    vector<int> arr = { 1, 2, 3, 4, 5 };
    int n = arr.size();
    int k = 3;
    minRange(arr, n, k);
    return 0;
}


